/* ===================== v0.51 · «Apagar Tudo» com barra de progresso ===================== */
function apagProg(){const P=['A preparar','Armazenamento local (definições e dados)','Bases de dados (turmas, fotografias, evidências)','Caches da aplicação','Serviços em segundo plano','Cookies'];
  const o=document.createElement('div');o.id='apagpg';o.innerHTML=`<div class="apgc" role="status" aria-live="polite"><div class="apgi">${ic('trash',26)}</div><h2>A apagar todos os dados</h2><p class="mut">Não feche esta janela.</p><div class="apgb"><i></i></div><div class="apgp"><b>0%</b><span></span></div><ol>${P.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div>`;document.body.appendChild(o);
  const st=(k,pc)=>{o.querySelector('.apgb i').style.width=pc+'%';o.querySelector('.apgp b').textContent=Math.round(pc)+'%';o.querySelector('.apgp span').textContent=P[k]||'';o.querySelectorAll('li').forEach((li,j)=>{li.className=j<k?'ok':j===k?'on':''})};
  return {p:k=>new Promise(r=>{st(k,(k/P.length)*100);setTimeout(r,420)}),fim:()=>new Promise(r=>{st(P.length,100);const c=o.querySelector('.apgc');c.classList.add('fim');c.querySelector('.apgi').innerHTML=ic('check',28);c.querySelector('h2').textContent='Todos os dados foram apagados';let n=3;const pp=c.querySelector('p');pp.textContent='A reiniciar em '+n+'…';const iv=setInterval(()=>{n--;pp.textContent=n>0?'A reiniciar em '+n+'…':'A reiniciar…';if(n<=0){clearInterval(iv);r()}},700)})}}

