/* ===================== v0.52 · Síntese descritiva: português padrão e linguagem pedagógica ===================== */
const _g=(a,m)=>a.genero==='F'?m.replace(/o$/,'a').replace(/os$/,'as'):m;
function artDom(nome){const raw=String(nome||'').trim();const txt=raw.split(/\s+/).map(p=>p.length>1&&p===p.toUpperCase()?p:p.toLowerCase()).join(' ');const w=normT(raw.split(/\s+/)[0]||'');
  const art=/(coes|oes|ades|agens|as|des)$/.test(w)?'as':/(os|es)$/.test(w)?'os':/(a|cao|ao|ade|agem|ice|ude)$/.test(w)?'a':'o';return [art,txt]}
function emDom(nome){const [a,t]=artDom(nome);return ({a:'na',o:'no',as:'nas',os:'nos'})[a]+' '+t}
function oDom(nome){const [a,t]=artDom(nome);return a+' '+t}
